/* eslint-disable max-len */

'use strict';

// MODULES //

var stride2offset = require( '@stdlib/strided/base/stride2offset' );
var ndarray = require( './ndarray.js' );


// MAIN //

/**
* Computes the Cartesian product for two double-precision floating-point strided arrays.
*
* @param {NonNegativeInteger} M - number of indexed elements of `x`
* @param {NonNegativeInteger} N - number of indexed elements of `y`
* @param {Float64Array} x - input array
* @param {integer} strideX - stride length for `x`
* @param {Float64Array} y - input array
* @param {integer} strideY - stride length for `y`
* @param {Float64Array} out - output array
* @param {integer} strideOut1 - stride length between consecutive output pairs
* @param {integer} strideOut2 - stride length between elements of each output pair
* @returns {Float64Array} output array
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = new Float64Array( [ 1.0, 2.0 ] );
* var y = new Float64Array( [ 3.0, 4.0 ] );
* var out = new Float64Array( 8 );
*
* dcartesianProduct( x.length, y.length, x, 1, y, 1, out, 2, 1 );
* // out => <Float64Array>[ 1.0, 3.0, 1.0, 4.0, 2.0, 3.0, 2.0, 4.0 ]
*/
function dcartesianProduct( M, N, x, strideX, y, strideY, out, strideOut1, strideOut2 ) {
	var ox = stride2offset( M, strideX );
	var oy = stride2offset( N, strideY );
	var oo = stride2offset( M * N, strideOut1 ) + stride2offset( 2, strideOut2 );
	return ndarray( M, N, x, strideX, ox, y, strideY, oy, out, strideOut1, strideOut2, oo );
}


// EXPORTS //

module.exports = dcartesianProduct;
